from pathlib import Path
import re
p=Path('strefa-wiedzy.html')
s=p.read_text(encoding='utf-8-sig')
def ref(pages):
    first=re.search(r'\d+',pages).group()
    return f'<p class="book-reference">Źródło: K. Daukszewicz, P. Kamiński, <a href="assets/ursus-fabryka-miasto-ludzie.pdf#page={first}" target="_blank" rel="noopener noreferrer">Ursus. Fabryka, miasto, ludzie, s. {pages} ↗</a>.</p>'
adds={
'czechowice': '''<h3>5. Od rolniczych wsi do osady przemysłowej</h3>
<p>Przez stulecia tereny dzisiejszego Ursusa miały przede wszystkim charakter rolniczy. Czechowice były podzielone między wielu właścicieli — w XVI wieku było ich dziesięciu. Wśród właścicieli pojawia się rodzina Czechowskich herbu Oksza, do którego nawiązuje nazwa jednej z ulic na Szamotach.</p>
<p>Około 1890 roku Skorosze stały się siedzibą rozległej gminy Pruszków. Gmina Skorosze powstała w 1916 roku, w związku z nadaniem Pruszkowowi praw miejskich i zmianami granic administracyjnych. Rozwój fabryki i połączeń kolejowych stopniowo przekształcił okoliczne wsie w osadę przemysłową.</p>''' + ref('9–12') + '''<aside class="source-difference"><strong>Różnica w datowaniu kapliczki:</strong> wcześniejsze materiały na tej stronie wskazują przełom XVIII i XIX wieku. Autorzy nowej książki podają około 1705 roku i przywołują legendę o jej powstaniu po bitwie ze Szwedami. Opisują także uszkodzenie podczas przenosin w 1987 roku oraz rekonstrukcję w latach 1994–2005. Datowania te należy rozróżniać, korzystając z odpowiedniego źródła.</aside>''' + ref('86'),
'p7p': '''<h3>5. Co oznacza nazwa Ursus?</h3><p>Łacińskie słowo <strong>ursus oznacza niedźwiedzia</strong>. Nazwa zakładu nawiązuje do siłacza z powieści „Quo Vadis” Henryka Sienkiewicza. Początkowo przedsiębiorstwo wytwarzało aparaturę dla cukrowni i gorzelni, a jego wyroby trafiały m.in. na rynek rosyjski. Po odzyskaniu niepodległości w 1918 roku utrata zamówień ze wschodu wymusiła zwrot ku odbiorcom w Polsce.</p>''' + ref('10–11') + '''<aside class="source-difference"><strong>Daty w różnych opracowaniach:</strong> dotychczasowy materiał wskazuje 1902 rok jako moment przyjęcia nazwy. W rozdziale „Siedem Panien” nowej książki rozszerzenie produkcji o silniki i zmianę oznaczenia opisano jako około 1903 roku, z zaznaczeniem, że niektóre źródła podają 1907 rok.</aside>''' + ref('61'),
'ciagowka': '''<h3>5. Fabryka samochodów i wojskowych pojazdów</h3><p>W maju 1924 roku zakłady wygrały przetarg Ministerstwa Spraw Wojskowych na dostawę <strong>1050 samochodów wojskowych</strong>. Pierwszy etap budowy fabryki zakończono w 1928 roku. Wytwarzano samochody ciężarowe i autobusy Ursus A na licencji włoskiej firmy S.P.A. W latach trzydziestych, po przejściu pod kontrolę państwa, zakłady produkowały także czołgi, silniki lotnicze i motocykle Sokół.</p>''' + ref('10, 13, 16–17') + '''<h3>6. Odbudowa po wojnie</h3><p>Niemcy wywieźli maszyny zakładowe na Dolny Śląsk. Po wojnie zespół kierowany przez inżyniera <strong>Bolesława Koehlera</strong> poszukiwał ich m.in. w Oławie, Chocianowie i Strzegomiu. Odzyskany sprzęt pozwolił odbudować produkcję. Pod nadzorem <strong>Edwarda Habicha</strong> opracowano ciągnik oparty na konstrukcji Lanz Bulldog, początkowo oznaczany LB-45, a następnie C-45. W 1947 roku wznowiono produkcję ciągników.</p>''' + ref('23–24') + '''<h3>7. Licencja Massey-Ferguson</h3><p>Umowa licencyjna z 1974 roku miała umożliwić wejście na kolejne rynki i rozszerzyć sieć serwisową. Na potrzeby produkcji powstały nowe hale w rejonie dzisiejszych ulic Posag 7 Panien, Licencyjnej i Kompanii AK „Goplana”. Jedną z trudności wdrożenia była dokumentacja oparta na brytyjskim systemie miar.</p>''' + ref('31'),
'wojna': '''<h3>3. Okupacja i konspiracja</h3><p>Według książki wojska niemieckie wkroczyły do Czechowic <strong>8 września 1939 roku</strong>. Zakłady podporządkowano potrzebom okupanta i nazywano w skrócie „Waverma”. Pierwsza lokalna grupa konspiracyjna powstała w listopadzie 1939 roku. W Czechowicach działały m.in. kompanie AK „Kordian” i „Goplana”.</p>''' + ref('19–20') + '''<h3>4. Pomoc uchodźcom z Warszawy</h3><p>Od 5 sierpnia 1944 roku do Czechowic napływali uchodźcy z Woli i Ochoty. Zorganizowano dla nich szpital w domu przy dawnej ul. Piłsudskiego 16, dzisiaj Bohaterów Warszawy 31. Trzydziestołóżkową placówkę uruchomiono w dwa dni. Przygotowaniem wyposażenia zajmowała się służba sanitarna Wojskowej Służby Kobiet AK kierowana przez Jadwigę Lesnobrodzką.</p>
<p>Żołnierze plutonu „Torpeda”, wywodzący się z Czechowic, walczyli w Powstaniu Warszawskim od Woli po Czerniaków. Po jego upadku teren fabryki służył jako obóz przejściowy dla wysiedlanych mieszkańców Warszawy. W styczniu 1945 roku żołnierze „Torpedy” uczestniczyli w rozminowaniu zakładów.</p>''' + ref('21–23'),
'czerwiec': '''<h3>4. Życie w mieście fabrycznym</h3><p>Zakłady organizowały nie tylko pracę, ale także wiele usług dla mieszkańców: edukację zawodową, żłobek, przedszkole, stołówkę i wypoczynek. Dom Kultury był miejscem koncertów i seansów filmowych. Z lokalnym życiem kulturalnym związani byli m.in. Aleksander Bardini i zespół Maanam.</p>''' + ref('25–26') + '''<h3>5. Niedźwiadek i rozwój miasta</h3><p>Prace przygotowawcze do budowy Niedźwiadka rozpoczęły się w 1964 roku. Konkurs architektoniczny ogłoszony rok później wygrał zespół Stefana Putowskiego. Osiedle otrzymało szkoły, zieleń i rzeźby, w tym charakterystyczną postać Onufrego Zagłoby. Nie wszystkie elementy projektu powstały — na przystanek kolejowy Ursus Niedźwiadek mieszkańcy czekali do lat 2013–2014.</p>''' + ref('28–29, 67') + '''<h3>6. Represje i pamięć o Czerwcu</h3><p>Protest 25 czerwca 1976 roku był odpowiedzią na zapowiedziane podwyżki cen. Po blokadzie torów nastąpiła brutalna interwencja milicji, aresztowania, procesy i zwolnienia z pracy. Represjonowanym i ich rodzinom pomagali przedstawiciele środowisk opozycyjnych, zapewniając wsparcie materialne oraz prawne.</p><p><strong>Pomnik Czerwca 1976 roku odsłonięto 4 września 1981 roku</strong>. Upamiętnia protest robotników i solidarność z prześladowanymi.</p>''' + ref('31–34, 94') + '''<h3>7. Od Ochoty do własnej dzielnicy</h3><p>Po włączeniu do Warszawy w 1977 roku Ursus należał do Ochoty. <strong>1 stycznia 1993 roku</strong> został z niej wydzielony jako odrębna dzielnica. W wyniku reformy warszawskiej z 1994 roku stał się gminą Warszawa-Ursus, natomiast reforma z 2002 roku włączyła go do struktury dzielnic jednolitego samorządu Warszawy.</p>''' + ref('35–38')
}
for topic,content in adds.items():
    pattern=rf'(<section id="temat-{topic}".*?)(\s*</div>\s*<div class="study-toolbar article-actions")'
    s,n=re.subn(pattern,lambda m:m[1]+'\n'+content+m[2],s,count=1,flags=re.S)
    assert n==1,topic
bibliography='''<section class="study-bibliography" aria-labelledby="bibliography-title">
<h2 id="bibliography-title">Bibliografia</h2>
<div class="bibliography-grid">
<article class="study-source"><div><p class="eyebrow">MAZOWIECKA BIBLIOTEKA CYFROWA</p><h3>Monografia varsavianistyczna: Ursuviana</h3><p>Dotychczasowy materiał źródłowy strefy wiedzy.</p></div><a class="study-button study-button-outline" href="https://mbc.cyfrowemazowsze.pl/dlibra/publication/79499/edition/74944/content" target="_blank" rel="noopener noreferrer">Otwórz publikację ↗</a></article>
<article class="study-source"><div><p class="eyebrow">KRZYSZTOF DAUKSZEWICZ · PAWEŁ KAMIŃSKI</p><h3>Ursus. Fabryka, miasto, ludzie</h3><p>Przekazana wersja PDF, 112 stron. Historia, biografie i miejsca warte poznania.</p></div><a class="study-button study-button-outline" href="assets/ursus-fabryka-miasto-ludzie.pdf" target="_blank" rel="noopener noreferrer">Otwórz książkę PDF ↗</a></article>
</div></section>'''
s,n=re.subn(r'<aside class="study-source">.*?</aside>',lambda m:bibliography,s,count=1,flags=re.S);assert n==1
new_topics=[
('kolej','Kolej i rozwój Ursusa','1913 • 1926 • 1936 • 1971','Jak kolej zmieniła okoliczne wsie w miasto',
'''<div><span>Najważniejsze fakty:</span><ul><li>1913 — uruchomienie przystanku Gołąbki.</li><li>1926 — powstanie przystanku Ursus; regularne postoje opisano od rozkładu z 15 maja 1927 roku.</li><li>1936 — elektryfikacja linii i charakterystyczne wiaty.</li><li>1971 — przystanek Ursus Północny projektu Arseniusza Romanowicza.</li></ul></div>
<h3>Fabryka potrzebowała kolei</h3><p>Bliskość linii kolejowych sprzyjała lokalizacji zakładów: umożliwiała budowę bocznic do przewozu materiałów i gotowych wyrobów. Połączenie Warszawa–Kalisz miało z kolei duży wpływ na rozwój Gołąbek, gdzie w 1913 roku uruchomiono przystanek.</p>
<h3>Robotnicy zabiegają o przystanek</h3><p>Pracownicy fabryki musieli początkowo dochodzić ze stacji Włochy albo Utrata, czyli dzisiejszego Piastowa. Książka opisuje zatrzymywanie przez nich pociągów hamulcem i ogniskami na torach. Powstanie przystanku w 1926 roku, interwencja prezydenta Ignacego Mościckiego i wprowadzenie regularnych postojów w 1927 roku poprawiły dojazdy do pracy.</p>
<h3>Architektura przystanków</h3><p>Rozpoznawalne wiaty na przystanku Ursus wiążą się z elektryfikacją linii w 1936 roku. Ursus Północny powstał w 1971 roku według projektu Arseniusza Romanowicza. Przystanek Ursus Niedźwiadek zrealizowano dopiero w latach 2013–2014.</p>'''+ref('10, 12–14, 29–30, 78')),
('postacie','Ludzie Ursusa','Społecznicy • Lekarze • Inżynierowie','Postacie, które warto znać',
'''<div><span>Zapamiętaj powiązania:</span><ul><li>Franciszek Adolf Acher — OSP i Park Achera.</li><li>Marian Krawczyk „Janos” — kompania „Kordian”.</li><li>Jerzy Włoczewski „Mazur” — kardiolog i lekarz AK.</li><li>Władysława Lesnobrodzka-Włoczewska „Wróbel” — pediatra i szpital polowy.</li></ul></div>
<h3>Franciszek Adolf Acher</h3><p>Wójt gminy Skorosze i działacz społeczny, w 1925 roku założyciel oraz pierwszy prezes miejscowej Ochotniczej Straży Pożarnej. Wspierał budowę Szkoły Powszechnej. Jego nazwisko upamiętnia park na terenie dawnego gospodarstwa.</p>'''+ref('49')+'''
<h3>Marian Krawczyk i Jerzy Włoczewski</h3><p>Marian Krawczyk, pseudonim „Janos”, współorganizował lokalną konspirację i od 1941 roku dowodził 10. Kompanią „Kordian”. Jerzy Włoczewski, pseudonim „Mazur”, był kardiologiem, komendantem placówki „Kordian” i lekarzem oddziałów AK. Prowadził szkolenia sanitarne dla drużyn z Ursusa, Piastowa i Pruszkowa.</p>'''+ref('55, 59')+'''
<h3>Władysława Lesnobrodzka-Włoczewska</h3><p>Lekarka pediatra i porucznik AK, pseudonim „Wróbel”, we wrześniu 1939 roku zorganizowała szpital polowy w Szkole Powszechnej. Od sierpnia 1944 roku pomagała pacjentom szpitala powstańczego. Prowadziła również poradnię dla dzieci.</p>'''+ref('60')+'''
<h3>Inżynierowie odbudowy</h3><p>Bolesław Koehler kierował powojenną akcją odzyskiwania maszyn wywiezionych z Ursusa. Edward Habich nadzorował prace nad ciągnikiem, który stał się modelem C-45.</p>'''+ref('23, 55')),
('miejsca','Rozpoznaj miejsce','Parki • Zabytki • Pomniki','Miejsca i symbole Ursusa',
'''<div><span>Przygotowanie do pytań graficznych:</span><ul><li>Pomnik Czerwca 1976 — kamień na postumencie i metalowy krzyż.</li><li>Park Czechowicki — staw i pamięć o dawnej nazwie miasta.</li><li>Acherówka i Park Achera — ślady rodziny społeczników.</li><li>Niedźwiedź na Skoroszach — symbol związany z nazwą Ursus.</li></ul></div>
<h3>Pomnik Czerwca 1976 roku</h3><p>Pomnik autorstwa Leszka Nadstawnego i pracowników zakładów odsłonięto 4 września 1981 roku. Stoi przy ul. Traktorzystów i pl. Czerwca 1976 roku, obok urzędu dzielnicy. Wykonano go z piaskowca osadzonego na granitowym postumencie; obok znajduje się metalowy krzyż.</p>'''+ref('94–95')+'''
<h3>Park Czechowicki</h3><p>Park przy ul. Michała Spisaka powstał około 1972 roku, wokół stawu. Nazwę nadano mu w 1998 roku, upamiętniając wieś i miasto Czechowice, które od 1954 roku nosiło nazwę Ursus.</p>'''+ref('80')+'''
<h3>Acherówka i Park Achera</h3><p>Budynek przy ul. Walerego Sławka wzniesiono w 1862 roku, a w 1912 roku przeszedł na własność Acherów. Na początku XXI wieku rozebrano go i odbudowano w zmienionej formie. Pobliskiego parku patronem jest od 1998 roku Franciszek Adolf Acher.</p>'''+ref('84')+'''
<h3>Rzeźba niedźwiedzia na Skoroszach</h3><p>Trzymetrowa rzeźba u zbiegu ulic Prystora i Ryżowej stanęła w listopadzie 2009 roku. Autorką zwycięskiego projektu była Aleksandra Ławicka-Cuper, a mieszkańcy uczestniczyli w wyborze pracy. Rzeźba powstała w Centrum Rzeźby Polskiej w Orońsku.</p>'''+ref('95')+'''
<h3>Rzeźby Niedźwiadka</h3><p>Elementem kompozycji osiedla były rzeźby, m.in. postać Jana Onufrego Zagłoby przy ulicy Zagłoby. Tworzyły one przestrzeń publiczną obok bloków, szkół i zieleni.</p>'''+ref('29, 67'))
]
cards=[];panels=[]
for key,tag,period,title,body in new_topics:
    cards.append(f'<a class="study-card" href="#temat-{key}" data-topic="{key}"><div class="study-meta"><span class="study-tag">{tag}</span><span>{period}</span></div><h2>{title}</h2><span class="study-read">Czytaj pełne opracowanie <span aria-hidden="true">→</span></span></a>')
    panels.append(f'''<section id="temat-{key}" class="study-panel" aria-labelledby="title-{key}"><div class="study-toolbar"><a href="#tematy" data-back>← Wróć do wyboru tematów</a><a class="study-button" href="cwiczenia.html">Przejdź do ćwiczeń →</a></div><article class="study-article"><header class="article-heading"><div class="study-meta"><span class="study-tag">{tag}</span><span>{period}</span></div><h2 id="title-{key}" tabindex="-1">{title}</h2></header><div class="article-body">{body}</div><div class="study-toolbar article-actions"><a href="#tematy" data-back>← Wybierz inny temat</a><a class="study-button" href="cwiczenia.html">Przejdź do ćwiczeń →</a></div></article></section>''')
s=s.replace('</a></div>\n      <div class="study-bottom">','</a>\n'+'\n'.join(cards)+'</div>\n      <div class="study-bottom">',1)
s=s.replace('  </main>','\n'.join(panels)+'\n  </main>',1)
p.write_text(s,encoding='utf-8')
assert len(re.findall('data-topic=',s))==8
assert len(re.findall('class="study-panel"',s))==8
print('Dodano bibliografię, uzupełnienia 5 tematów i 3 nowe opracowania.')
